package com.garagedesk.exception; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.Map; @RestControllerAdvice public class GlobalExceptionHandler{@ExceptionHandler(ResourceNotFoundException.class) @ResponseStatus(HttpStatus.NOT_FOUND) public Map<String,Object> nf(ResourceNotFoundException e){return Map.of("error",e.getMessage(),"status",404);}@ExceptionHandler(ConflictException.class) @ResponseStatus(HttpStatus.CONFLICT) public Map<String,Object> cf(ConflictException e){return Map.of("error",e.getMessage(),"status",409);}@ExceptionHandler(Exception.class) @ResponseStatus(HttpStatus.BAD_REQUEST) public Map<String,Object> ex(Exception e){return Map.of("error",e.getMessage()==null?"Request failed":e.getMessage(),"status",400);}}
